\":\"object\"},\"FixedForcedOutage\":{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Records a component's forced outage status directly rather than as a probability. outage_status is 1 when outaged, 0 when available; may be backed by a time series from simulation or historical records.\",\"properties\":{\"id\":{\"type\":\"integer\"},\"identifier\":{\"default\":null,\"description\":\"Optional user-supplied identifier for the outage, such as a name or a block id. Null when not set.\",\"type\":[\"string\",\"null\"]},\"monitored_components\":{\"default\":[],\"description\":\"IDs of devices whose post-contingency state to model for this outage. Empty by default.\",\"items\":{\"type\":\"integer\"},\"type\":\"array\",\"uniqueItems\":true},\"outage_status\":{\"type\":\"number\"}},\"required\":[\"id\",\"outage_status\"],\"title\":\"FixedForcedOutage\",\"type\":\"object\"},\"FromTo\":{\"description\":\"A pair of values, one at the `from` end and one at the `to` end of a directed edge.\",\"properties\":{\"from\":{\"title\":\"From\",\"type\":\"number\"},\"to\":{\"title\":\"To\",\"type\":\"number\"}},\"title\":\"FromTo\",\"type\":\"object\"},\"FromTo_ToFrom\":{\"description\":\"A pair of values for a directed edge, one for each orientation: `from_to` and `to_from`. The two are carried separately because the quantity need not be equal in the two directions.\",\"properties\":{\"from_to\":{\"title\":\"FromTo\",\"type\":\"number\"},\"to_from\":{\"title\":\"ToFrom\",\"type\":\"number\"}},\"title\":\"FromTo_ToFrom\",\"type\":\"object\"},\"FuelCurve\":{\"description\":\"Variable operation cost of a device in fuel consumed (MBTU, liters, m^3) plus the price converting fuel to currency. Wraps a ValueCurve; exactly one of fuel_cost and fuel_cost_time_series supplies the price.\",\"properties\":{\"fuel_cost\":{\"description\":\"Fixed fuel cost per unit of fuel, or null when fuel_cost_time_series supplies a time-varying one. Exactly one of the two is set.\"